import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
from scipy.optimize import minimize
rw=Chem.RWMol(); coords=[]; names={}
def atom(el,p,name=None,arom=False):
 a=Chem.Atom(el); a.SetIsAromatic(arom);i=rw.AddAtom(a);coords.append(np.array(p,float));
 if name:names[name]=i
 return i
def bond(a,b,t=Chem.BondType.SINGLE):rw.AddBond(a,b,t)
ar=[[0,2.75,0],[0,4.15,0],[-1.212,2.05,0],[-2.424,2.75,0],[-2.424,4.15,0],[-1.212,4.85,0],[1.212,2.05,0],[2.424,2.75,0],[2.424,4.15,0],[1.212,4.85,0]]
for i,p in enumerate(ar):atom('N' if i in [2,6] else 'C',p,arom=True)
for a,b in [(0,1),(0,2),(2,3),(3,4),(4,5),(5,1),(0,6),(6,7),(7,8),(8,9),(9,1)]:bond(a,b,Chem.BondType.AROMATIC)
def unit(x):return x/np.linalg.norm(x)
for side,ring in [('L',3),('R',7)]:
 def tr(p):return np.array(p)*([1,1,1] if side=='L' else [-1,1,-1])
 ch=atom('C',tr([-3.65,1.8,-.35]),side+'ch');bond(ring,ch)
 p=atom('P',tr([-3.3,.3,-1.4]),side+'p');bond(ch,p)
 c=atom('C',tr([-4.05,1.05,.95]),side+'imc');bond(ch,c)
 n=atom('N',tr([-3.2,.1,1.25]),side+'imn');bond(c,n,Chem.BondType.DOUBLE)
 me=atom('C',tr([-5.35,.85,1.0]));bond(c,me)
 # two tBu substituents around P, away from CH and metal
 v1=unit(coords[ch]-coords[p]); v2=unit(tr([-1.7,0,0])-coords[p]);bis=unit(v1+v2);perp=unit(np.cross(v1,v2))
 for t,vec in enumerate([-bis*.58+perp*.815,-bis*.58-perp*.815]):
  cent=atom('C',coords[p]+1.88*vec);bond(p,cent)
  u=unit(coords[p]-coords[cent]);e=unit(np.cross(u,[0,1,0]));f=np.cross(u,e)
  for k in range(3):
   d=-u/3+np.sqrt(8/9)*(e*np.cos(2*np.pi*k/3)+f*np.sin(2*np.pi*k/3))
   met=atom('C',coords[cent]+1.53*d);bond(cent,met)
 # nitrile
 nn=atom('N',tr([-1.7,-2.05,0]),side+'acn');cc=atom('C',tr([-1.7,-3.2,0]));cm=atom('C',tr([-1.7,-4.65,0]));bond(nn,cc,Chem.BondType.TRIPLE);bond(cc,cm)
mol=rw.GetMol();Chem.SanitizeMol(mol)
conf=Chem.Conformer(mol.GetNumAtoms())
for i,p in enumerate(coords):conf.SetAtomPosition(i,p)
mol.AddConformer(conf)
mol=Chem.AddHs(mol,addCoords=True)
conf=mol.GetConformer(); x=np.array(conf.GetPositions());norg=len(x)
# place imine H consistent with metal as third planar partner
for s in ['L','R']:
 n=names[s+'imn']; c=names[s+'imc']; hi=[a.GetIdx() for a in mol.GetAtomWithIdx(n).GetNeighbors() if a.GetSymbol()=='H'][0]
 ru=np.array([-1.7 if s=='L' else 1.7,0,0]);hdir=-unit(unit(x[c]-x[n])+unit(ru-x[n]));x[hi]=x[n]+1.02*hdir
 for i,p in enumerate(x):conf.SetAtomPosition(i,p)
print('organic',Chem.MolToSmiles(Chem.RemoveHs(mol)),norg,names,flush=True)
mp=AllChem.MMFFGetMoleculeProperties(mol)
print('MMFF available',mp is not None,flush=True)
ff=AllChem.MMFFGetMoleculeForceField(mol,mp,ignoreInterfragInteractions=False)
# append metals and bridge chlorides
x=np.vstack([x,[-1.7,0,0],[1.7,0,0],[0,0,-1.73],[0,0,1.73]])
ruL,ruR,clB,clF=range(norg,norg+4)
pairs=[];angles=[]
for s,ru,arN in [('L',ruL,2),('R',ruR,6)]:
 ns=[arN,names[s+'acn'],names[s+'p'],names[s+'imn'],clB,clF]
 lens=[2.12,2.04,2.30,2.12,2.44,2.44]
 for a,d in zip(ns,lens):pairs.append((ru,a,d,180))
 # octahedral axes Nnaph/Nacn, P/Clfront(left) or back(right), Nim/Clother
 trans={frozenset([arN,names[s+'acn']]),frozenset([names[s+'p'],clF if s=='L' else clB]),frozenset([names[s+'imn'],clB if s=='L' else clF])}
 for i in range(6):
  for j in range(i+1,6):angles.append((ns[i],ru,ns[j],-1 if frozenset([ns[i],ns[j]]) in trans else 0,35 if frozenset([ns[i],ns[j]]) in trans else 25))
 # coordination donor geometry
 for a in mol.GetAtomWithIdx(arN).GetNeighbors():angles.append((a.GetIdx(),arN,ru,-.5,10))
 ni=names[s+'imn']
 for a in mol.GetAtomWithIdx(ni).GetNeighbors():angles.append((a.GetIdx(),ni,ru,-.5,25))
 ac=names[s+'acn'];cc=mol.GetAtomWithIdx(ac).GetNeighbors()[0].GetIdx();angles.append((cc,ac,ru,-1,70))
 # coordinated phosphine approximately tetrahedral
 for a in mol.GetAtomWithIdx(names[s+'p']).GetNeighbors():angles.append((a.GetIdx(),names[s+'p'],ru,-1/3,10))
# repulsions to metal/chloride and among inorganic (no Ru-Ru constraint)
rep=[]
for a in range(norg,norg+4):
 linked={b for aa,b,_,_ in pairs if aa==a}|{aa for aa,b,_,_ in pairs if b==a}
 for b in range(a):
  if b in linked:continue
  if b>=norg:r0=3.05 if b in [ruL,ruR] and a in[ruL,ruR] else 3.1
  else:
   sym=mol.GetAtomWithIdx(b).GetSymbol();r0=({'H':2.25,'C':2.9,'N':2.7,'P':3.1}[sym] if a>=clB else {'H':2.05,'C':2.65,'N':2.5,'P':2.7}[sym])
  rep.append((a,b,r0,12))
initial=x.copy()
def calc(flat,restr=0):
 q=flat.reshape(-1,3); E=ff.CalcEnergy(q[:norg].ravel().tolist());g=np.zeros_like(q);g[:norg]=np.array(ff.CalcGrad(q[:norg].ravel().tolist())).reshape(-1,3)
 for a,b,d,k in pairs:
  v=q[a]-q[b];r=np.linalg.norm(v);dr=r-d;E+=k*dr*dr;dg=2*k*dr*v/r;g[a]+=dg;g[b]-=dg
 for a,b,c,t,k in angles:
  u=q[a]-q[b];v=q[c]-q[b];l=np.linalg.norm(u);r=np.linalg.norm(v);nu=u/l;nv=v/r;co=nu@nv;d=co-t;E+=k*d*d
  ga=2*k*d*(nv-co*nu)/l;gc=2*k*d*(nu-co*nv)/r;g[a]+=ga;g[c]+=gc;g[b]-=ga+gc
 for a,b,r0,k in rep:
  v=q[a]-q[b];r=np.linalg.norm(v)
  if r<r0:
   E+=k*(r-r0)**2;dg=2*k*(r-r0)*v/r;g[a]+=dg;g[b]-=dg
 if restr:
  inds=list(range(10))+[ruL,ruR,clB,clF];d=q[inds]-initial[inds];E+=restr*np.sum(d*d);g[inds]+=2*restr*d
 return E,g.ravel()
for restr in [20,2,0]:
 result=minimize(lambda p:calc(p,restr),x.ravel(),jac=True,method='L-BFGS-B',options={'maxiter':1800,'ftol':1e-10,'gtol':1e-4})
 x=result.x.reshape(-1,3);print('opt',restr,result.fun,result.message,flush=True)
for i,p in enumerate(x[:norg]):conf.SetAtomPosition(i,p)
Chem.MolToMolFile(mol,'ligand.mol')
elems=[a.GetSymbol() for a in mol.GetAtoms()]+['Ru','Ru','Cl','Cl']
def write(path,x):
 with open(path,'w') as f:
  f.write(f'{len(x)}\nDinuclear Ru(II) complex, charge +2; explicit hydrogens\n')
  for el,p in zip(elems,x):f.write(f'{el:2s} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
write('initial.xyz',x)
np.savez('structure.npz',coords=x,elems=elems,names=names)
print('done',len(x),flush=True)
